pragma solidity ^0.8.0;

import {IAddressProvider} from 'src/interfaces/IAddressProvider.sol';
import {IACLManager} from 'src/interfaces/IACLManager.sol';

import {Constants} from 'src/libraries/helpers/Constants.sol';
import {Errors} from 'src/libraries/helpers/Errors.sol';
import {StorageSlot} from 'src/libraries/logic/StorageSlot.sol';
import {DataTypes} from 'src/libraries/types/DataTypes.sol';

import {Base} from 'src/base/Base.sol';
import {Proxy} from 'src/base/Proxy.sol';

/// @notice Main storage contract
contract PoolManager is Base {
  string public constant name = 'Bend Protocol V2';

  constructor(address provider_, address installerModule) {
    reentrancyLock = Constants.REENTRANCYLOCK__UNLOCKED;

    DataTypes.PoolStorage storage ps = StorageSlot.getPoolStorage();
    ps.addressProvider = provider_;
    ps.nextPoolId = Constants.INITIAL_POOL_ID;

    ps.wrappedNativeToken = IAddressProvider(ps.addressProvider).getWrappedNativeToken();
    require(ps.wrappedNativeToken != address(0), Errors.INVALID_ADDRESS);

    moduleLookup[Constants.MODULEID__INSTALLER] = installerModule;
    address installerProxy = _createProxy(Constants.MODULEID__INSTALLER);
    trustedSenders[installerProxy].moduleImpl = installerModule;
  }

  /// @notice Lookup the current implementation contract for a module
  /// @param moduleId Fixed constant that refers to a module type
  /// @return An internal address specifies the module's implementation code
  function moduleIdToImplementation(uint moduleId) external view returns (address) {
    return moduleLookup[moduleId];
  }

  /// @notice Lookup a proxy that can be used to interact with a module (only valid for single-proxy modules)
  /// @param moduleId Fixed constant that refers to a module type
  /// @return An address that should be cast to the appropriate module interface
  function moduleIdToProxy(uint moduleId) external view returns (address) {
    return proxyLookup[moduleId];
  }

  function dispatch() external payable reentrantOK {
    // only trusted proxy
    uint32 moduleId = trustedSenders[msg.sender].moduleId;
    address moduleImpl = trustedSenders[msg.sender].moduleImpl;

    require(moduleId != 0, Errors.PROXY_SENDER_NOT_TRUST);

    // multi proxy module
    if (moduleImpl == address(0)) moduleImpl = moduleLookup[moduleId];

    uint msgDataLength = msg.data.length;
    require(msgDataLength >= (4 + 4 + 20), Errors.PROXY_MSGDATA_TOO_SHORT);

    assembly {
      let payloadSize := sub(calldatasize(), 4)
      calldatacopy(0, 4, payloadSize)
      mstore(payloadSize, shl(96, caller()))

      let result := delegatecall(gas(), moduleImpl, 0, add(payloadSize, 20), 0, 0)

      returndatacopy(0, 0, returndatasize())

      switch result
      case 0 {
        revert(0, returndatasize())
      }
      default {
        return(0, returndatasize())
      }
    }
  }

  receive() external payable {}

  modifier onlyPoolAdmin() {
    _onlyPoolAdmin();

    _;
  }

  function _onlyPoolAdmin() internal view {
    DataTypes.PoolStorage storage ps = StorageSlot.getPoolStorage();

    IACLManager aclManager = IACLManager(IAddressProvider(ps.addressProvider).getACLManager());
    require(aclManager.isPoolAdmin(msg.sender), Errors.CALLER_NOT_POOL_ADMIN);
  }

  /* @notice only used when user transfer ETH to contract by mistake */
  function emergencyEtherTransfer(address to, uint256 amount) public onlyPoolAdmin {
    (bool success, ) = to.call{value: amount}(new bytes(0));
    require(success, Errors.ETH_TRANSFER_FAILED);
  }

  /* @notice only used when user transfer ETH to module contract by mistake */
  function emergencyProxyEtherTransfer(address proxyAddr, address to, uint256 amount) public onlyPoolAdmin {
    Proxy proxy = Proxy(payable(proxyAddr));
    proxy.emergencyEtherTransfer(to, amount);
  }
}
"},"src/PriceOracle.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import {Initializable} from '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';

import {AggregatorV2V3Interface} from '@chainlink/contracts/src/v0.8/interfaces/AggregatorV2V3Interface.sol';
import {IBendNFTOracle} from './interfaces/IBendNFTOracle.sol';

import {IAddressProvider} from './interfaces/IAddressProvider.sol';
import {IACLManager} from './interfaces/IACLManager.sol';
import {IPriceOracle} from './interfaces/IPriceOracle.sol';
import {Constants} from './libraries/helpers/Constants.sol';
import {Errors} from './libraries/helpers/Errors.sol';
import {Events} from './libraries/helpers/Events.sol';

contract PriceOracle is IPriceOracle, Initializable {
  IAddressProvider public addressProvider;

  address public BASE_CURRENCY;
  uint256 public BASE_CURRENCY_UNIT;

  address public NFT_BASE_CURRENCY;
  uint256 public NFT_BASE_CURRENCY_UNIT;

  // BendDAO Protocol NFT Oracle which used by both v1 and v2
  IBendNFTOracle public bendNFTOracle;

  // Chainlink Aggregators for ERC20 tokens
  mapping(address => AggregatorV2V3Interface) public assetChainlinkAggregators;

  /**
   * @dev This empty reserved space is put in place to allow future versions to add new
   * variables without shifting down storage in the inheritance chain.
   * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
   */
  uint256[43] private __gap;

  modifier onlyOracleAdmin() {
    _onlyOracleAdmin();
    _;
  }

  function _onlyOracleAdmin() internal view {
    require(IACLManager(addressProvider.getACLManager()).isOracleAdmin(msg.sender), Errors.CALLER_NOT_ORACLE_ADMIN);
  }

  constructor() {
    _disableInitializers();
  }

  /**
   * @dev The ACL admin should be initialized at the addressesProvider beforehand
   */
  function initialize(
    address addressProvider_,
    address baseCurrency_,
    uint256 baseCurrencyUnit_,
    address nftBaseCurrency_,
    uint256 nftBaseCurrencyUnit_
  ) public initializer {
    require(addressProvider_ != address(0), Errors.ADDR_PROVIDER_CANNOT_BE_ZERO);
    addressProvider = IAddressProvider(addressProvider_);

    // if use US Dollars, baseCurrency will be 0 and unit is 1e8
    BASE_CURRENCY = baseCurrency_;
    BASE_CURRENCY_UNIT = baseCurrencyUnit_;

    NFT_BASE_CURRENCY = nftBaseCurrency_;
    NFT_BASE_CURRENCY_UNIT = nftBaseCurrencyUnit_;
  }

  /// @notice Set Chainlink aggregators for sssets
  function setAssetChainlinkAggregators(
    address[] calldata assets,
    address[] calldata aggregators
  ) public onlyOracleAdmin {
    require(assets.length == aggregators.length, Errors.INCONSISTENT_PARAMS_LENGTH);
    for (uint256 i = 0; i < assets.length; i++) {
      require(assets[i] != address(0), Errors.INVALID_ADDRESS);
      require(aggregators[i] != address(0), Errors.INVALID_ADDRESS);
      assetChainlinkAggregators[assets[i]] = AggregatorV2V3Interface(aggregators[i]);
      emit Events.AssetAggregatorUpdated(assets[i], aggregators[i]);
    }
  }

  function getAssetChainlinkAggregators(address[] calldata assets) public view returns (address[] memory aggregators) {
    aggregators = new address[](assets.length);
    for (uint256 i = 0; i < assets.length; i++) {
      aggregators[i] = address(assetChainlinkAggregators[assets[i]]);
    }
  }

  /// @notice Set the global BendDAO NFT Oracle
  function setBendNFTOracle(address bendNFTOracle_) public onlyOracleAdmin {
    require(bendNFTOracle_ != address(0), Errors.INVALID_ADDRESS);
    bendNFTOracle = IBendNFTOracle(bendNFTOracle_);
    emit Events.BendNFTOracleUpdated(bendNFTOracle_);
  }

  function getBendNFTOracle() public view returns (address) {
    return address(bendNFTOracle);
  }

  /// @notice Query the price of asset
  function getAssetPrice(address asset) external view returns (uint256) {
    if (asset == BASE_CURRENCY) {
      return BASE_CURRENCY_UNIT;
    }

    if (assetChainlinkAggregators[asset] != AggregatorV2V3Interface(address(0))) {
      return getAssetPriceFromChainlink(asset);
    }

    return getAssetPriceFromBendNFTOracle(asset);
  }

  /// @notice Query the price of asset from chainlink oracle
  function getAssetPriceFromChainlink(address asset) public view returns (uint256) {
    AggregatorV2V3Interface sourceAgg = assetChainlinkAggregators[asset];
    require(address(sourceAgg) != address(0), Errors.ASSET_AGGREGATOR_NOT_EXIST);

    (uint80 roundId, int256 answer, , uint256 updatedAt, uint80 answeredInRound) = sourceAgg.latestRoundData();
    require(answer > 0, Errors.ASSET_PRICE_IS_ZERO);
    require(updatedAt != 0, Errors.ORACLE_PRICE_IS_STALE);
    require(answeredInRound >= roundId, Errors.ORACLE_PRICE_IS_STALE);

    return uint256(answer);
  }

  /// @notice Query the price of asset from benddao nft oracle
  function getAssetPriceFromBendNFTOracle(address asset) public view returns (uint256) {
    uint256 nftPriceInNftBase = bendNFTOracle.getAssetPrice(asset);
    require(nftPriceInNftBase > 0, Errors.ASSET_PRICE_IS_ZERO);

    // nft oracle use the same currency with protocol
    if (NFT_BASE_CURRENCY == BASE_CURRENCY) {
      return nftPriceInNftBase;
    }

    // convert nft price to base currency, e.g. from ETH to USD
    uint256 nftBaseCurrencyPriceInBase = getAssetPriceFromChainlink(NFT_BASE_CURRENCY);
    uint256 nftPriceInBase = (nftPriceInNftBase * nftBaseCurrencyPriceInBase) / NFT_BASE_CURRENCY_UNIT;
    return nftPriceInBase;
  }
}
"},"src/base/Base.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import {Pausable} from '@openzeppelin/contracts/security/Pausable.sol';
import {ERC721Holder} from '@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol';

import {Constants} from 'src/libraries/helpers/Constants.sol';
import {Events} from 'src/libraries/helpers/Events.sol';
import {Errors} from 'src/libraries/helpers/Errors.sol';

import {Storage} from 'src/base/Storage.sol';
import {Proxy} from 'src/base/Proxy.sol';

abstract contract Base is Storage, Pausable, ERC721Holder {
  constructor() {
    reentrancyLock = Constants.REENTRANCYLOCK__UNLOCKED;
  }

  // Modules

  function _createProxy(uint proxyModuleId) internal returns (address) {
    require(proxyModuleId != 0, Errors.PROXY_INVALID_MODULE);
    require(proxyModuleId <= Constants.MAX_EXTERNAL_MODULEID, Errors.PROXY_INTERNAL_MODULE);

    // If we've already created a proxy for a single-proxy module, just return it:

    if (proxyLookup[proxyModuleId] != address(0)) return proxyLookup[proxyModuleId];

    // Otherwise create a proxy:

    address proxyAddr = address(new Proxy());

    if (proxyModuleId <= Constants.MAX_EXTERNAL_SINGLE_PROXY_MODULEID) proxyLookup[proxyModuleId] = proxyAddr;

    trustedSenders[proxyAddr] = TrustedSenderInfo({moduleId: uint32(proxyModuleId), moduleImpl: address(0)});

    emit Events.ProxyCreated(proxyAddr, proxyModuleId);

    return proxyAddr;
  }

  function callInternalModule(uint moduleId, bytes memory input) internal returns (bytes memory) {
    (bool success, bytes memory result) = moduleLookup[moduleId].delegatecall(input);
    if (!success) revertBytes(result);
    return result;
  }

  // Modifiers

  modifier nonReentrant() {
    require(reentrancyLock == Constants.REENTRANCYLOCK__UNLOCKED, Errors.REENTRANCY_ALREADY_LOCKED);

    reentrancyLock = Constants.REENTRANCYLOCK__LOCKED;
    _;
    reentrancyLock = Constants.REENTRANCYLOCK__UNLOCKED;
  }

  modifier reentrantOK() {
    // documentation only
    _;
  }

  // Used to flag functions which do not modify storage, but do perform a delegate call
  // to a view function, which prohibits a standard view modifier. The flag is used to
  // patch state mutability in compiled ABIs and interfaces.
  modifier staticDelegate() {
    _;
  }

  // Error handling

  function revertBytes(bytes memory errMsg) internal pure {
    if (errMsg.length > 0) {
      assembly {
        revert(add(32, errMsg), mload(errMsg))
      }
    }

    revert(Errors.EMPTY_ERROR);
  }
}
"},"src/base/BaseModule.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import {Base} from './Base.sol';

abstract contract BaseModule is Base {
  // Construction

  // public accessors common to all modules

  uint public immutable moduleId;
  bytes32 public immutable moduleGitCommit;

  constructor(uint moduleId_, bytes32 moduleGitCommit_) {
    moduleId = moduleId_;
    moduleGitCommit = moduleGitCommit_;
  }

  // Accessing parameters

  function unpackTrailingParamMsgSender() internal pure returns (address msgSender) {
    assembly {
      msgSender := shr(96, calldataload(sub(calldatasize(), 40)))
    }
  }

  function unpackTrailingParams() internal pure returns (address msgSender, address proxyAddr) {
    assembly {
      msgSender := shr(96, calldataload(sub(calldatasize(), 40)))
      proxyAddr := shr(96, calldataload(sub(calldatasize(), 20)))
    }
  }

  // Emit logs via proxies
}
"},"src/base/Proxy.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

contract Proxy {
  address immutable creator;

  constructor() {
    creator = msg.sender;
  }

  // External interface

  receive() external payable {}

  fallback() external payable {
    address creator_ = creator;
    uint value = msg.value;

    if (msg.sender == creator_) {
      assembly {
        mstore(0, 0)
        calldatacopy(31, 0, calldatasize())

        switch mload(0) // numTopics
        case 0 {
          log0(32, sub(calldatasize(), 1))
        }
        case 1 {
          log1(64, sub(calldatasize(), 33), mload(32))
        }
        case 2 {
          log2(96, sub(calldatasize(), 65), mload(32), mload(64))
        }
        case 3 {
          log3(128, sub(calldatasize(), 97), mload(32), mload(64), mload(96))
        }
        case 4 {
          log4(160, sub(calldatasize(), 129), mload(32), mload(64), mload(96), mload(128))
        }
        default {
          revert(0, 0)
        }

        return(0, 0)
      }
    } else {
      assembly {
        mstore(0, 0xe9c4a3ac00000000000000000000000000000000000000000000000000000000) // dispatch() selector
        calldatacopy(4, 0, calldatasize())
        mstore(add(4, calldatasize()), shl(96, caller()))

        let result := call(gas(), creator_, value, 0, add(24, calldatasize()), 0, 0)
        returndatacopy(0, 0, returndatasize())

        switch result
        case 0 {
          revert(0, returndatasize())
        }
        default {
          return(0, returndatasize())
        }
      }
    }
  }

  /* @notice only used when user transfer ETH to contract by mistake */
  function emergencyEtherTransfer(address to, uint256 amount) public {
    require(msg.sender == creator, 'Invalid caller');

    (bool success, ) = to.call{value: amount}(new bytes(0));
    require(success, 'ETH_TRANSFER_FAILED');
  }
}
